{
  "technical_and_design_decisions": [
    "Implement tenant-specific ZK metadata isolation through a configurable namespace value, with the effective namespace consistently applied to all metadata paths.",
    "Prompt for Admin server username and password through xd-shell or the relevant interactive client, keep credentials in memory only, and ensure passwords are excluded from command history, logs, and exception messages.",
    "Use a dedicated maintenance branch for MINOR releases and preserve MASTER for ongoing development; add lightweight branch and release documentation rather than automating the entire release process.",
    "Remove deprecated module-registry functions after auditing all references, including Shell and Admin-UI modules, and preserve compatibility only where existing supported behavior requires it.",
    "For random Admin server ports, publish the resolved server endpoint through the existing ZK integration and have xd-shell discover it. Do not introduce a load balancer in this increment.",
    "Update Kafka integration and tests to the rewritten consumer API while retaining the existing message-bus abstraction.",
    "Treat U7 as a feasibility and design spike, as explicitly stated in the specification. Research Motion-JPEG streaming and produce an implementation-oriented design without committing to a production computer-vision implementation.",
    "Implement the message-rate setting as a servers.yml configuration property with a safe default that preserves current behavior, and propagate it to the cluster-view presentation layer.",
    "Use existing project conventions, test frameworks, build tooling, logging infrastructure, ZK clients, and UI frameworks unless the implementation requires a small localized extension."
  ],
  "assumptions": [
    "The increment is implemented in an existing Spring-based codebase with functioning local builds, test infrastructure, Admin server, xd-shell, ZK integration, Kafka integration, and cluster-view UI.",
    "Requirements and acceptance details not specified in the stories will be inferred from current code behavior and existing project conventions.",
    "No major Spring, Java, application-server, ZK, Kafka, or frontend framework upgrade is required beyond the Kafka consumer API changes described in U6.",
    "Existing authentication and authorization mechanisms remain unchanged; U2 concerns secure interactive credential entry and handling, not redesigning Admin server authentication.",
    "The namespace configuration is supplied through existing application configuration mechanisms and applies to metadata paths, not to unrelated operational ZK data.",
    "The random-port solution assumes the Admin server can publish its bound port and that xd-shell can access the same ZK ensemble. Load-balancer deployment is out of scope.",
    "Deprecated APIs can be removed without supporting external binary compatibility for consumers outside the repository, or any required compatibility shims are small and localized.",
    "Kafka test failures are limited to consumer-rewrite compatibility and related timing or fixture changes; no redesign of the message-bus subsystem is required.",
    "For U7, the deliverable is a feasibility report, Motion-JPEG format and streaming design, compatibility analysis, and prototype-level validation where useful; production ingestion and facial-detection algorithms are out of scope.",
    "The message-rate configuration affects display or collection behavior already represented by the cluster view and does not require a new metrics backend.",
    "Estimates include implementation, unit/integration testing, debugging, code review preparation, and developer documentation, but exclude elapsed waiting time and work by other developers.",
    "The estimate represents one developer performing all activities and is expressed in work-hours."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Baseline repository and architecture analysis",
      "activity_description": "Inspect relevant Spring modules, configuration, ZK metadata paths, Admin server startup, xd-shell, Kafka integration, deprecated APIs, cluster-view UI, build scripts, and existing tests to establish implementation points and regression scope.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 namespace configuration implementation",
      "activity_description": "Add configurable namespace handling and apply it consistently to tenant-specific ZK metadata creation, lookup, updates, and cleanup paths.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 tests and configuration validation",
      "activity_description": "Add unit and integration coverage for default namespaces, custom namespaces, tenant isolation, path construction, and backward-compatible configuration behavior.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A4",
      "activity_name": "U2 secure interactive Admin credentials",
      "activity_description": "Implement username and masked password prompts, credential propagation to Admin server access, in-memory handling, and safeguards against logging or exposing the password.",
      "most_likely_effort": 44
    },
    {
      "activity_id": "A5",
      "activity_name": "U2 credential handling tests",
      "activity_description": "Test successful and failed authentication, empty or invalid input, non-interactive behavior where applicable, masking, command-history behavior, and log/exception redaction.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "U3 maintenance branch and release-process update",
      "activity_description": "Create or document the maintenance branch convention for MINOR releases, update branch/release guidance, and verify that build and versioning workflows work from the maintenance branch.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7",
      "activity_name": "U4 deprecated API inventory",
      "activity_description": "Locate deprecated module-registry functions and all references across core, Shell, Admin-UI, tests, documentation, and build configuration; classify each reference for removal or replacement.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A8",
      "activity_name": "U4 deprecated code cleanup",
      "activity_description": "Remove deprecated module-definition download and related functions, update callers to current registry APIs, clean Shell and Admin-UI usage, and remove obsolete wiring where safe.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A9",
      "activity_name": "U4 cleanup verification",
      "activity_description": "Update affected unit and integration tests, verify no stale references remain, and run module-registry, Shell, and Admin-UI test suites.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A10",
      "activity_name": "U5 random-port architecture spike",
      "activity_description": "Evaluate direct xd-shell-to-ZK discovery versus load-balancer interaction, inspect deployment constraints, and define the endpoint publication and discovery contract.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A11",
      "activity_name": "U5 endpoint publication and xd-shell discovery",
      "activity_description": "Publish the Admin server's runtime host and random Tomcat port in a defined ZK location, implement xd-shell lookup and connection behavior, and provide useful errors and configuration for the discovery path.",
      "most_likely_effort": 64
    },
    {
      "activity_id": "A12",
      "activity_name": "U5 discovery and random-port tests",
      "activity_description": "Test random-port startup, endpoint publication and cleanup, ZK availability failures, shell discovery, reconnect behavior, and compatibility with deployments using fixed ports.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "A13",
      "activity_name": "U6 Kafka consumer rewrite compatibility",
      "activity_description": "Update Kafka consumer integration, configuration, lifecycle handling, offsets, polling, and adapters to the rewritten consumer API while preserving existing message-bus semantics.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A14",
      "activity_name": "U6 failing-test rerun and remediation",
      "activity_description": "Run the Kafka-related test suites, diagnose failures caused by the consumer rewrite, adjust fixtures and timing assumptions, fix regressions, and verify producer-consumer interoperability.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A15",
      "activity_name": "U7 Motion-JPEG feasibility research",
      "activity_description": "Research Motion-JPEG framing, transport options, encoding and decoding libraries, streaming constraints, JVM and platform compatibility, and suitability for downstream facial-detection processing.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "A16",
      "activity_name": "U7 Motion-JPEG design specification",
      "activity_description": "Produce design specifications for stream ingestion, frame boundaries, metadata, buffering, backpressure, error handling, APIs, deployment, security, and integration points for predictive analytics.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A17",
      "activity_name": "U8 message-rate configuration implementation",
      "activity_description": "Add a servers.yml configuration parameter for enabling or disabling message rates, load and validate the setting, propagate it through cluster-view services, and preserve the selected default behavior.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A18",
      "activity_name": "U8 configuration and UI tests",
      "activity_description": "Test default and explicit configuration values, invalid configuration handling, cluster propagation, enabled and disabled rendering, and backward compatibility of the cluster view.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A19",
      "activity_name": "Cross-feature integration and regression testing",
      "activity_description": "Run the complete build and relevant integration suites, exercise combined configuration and ZK scenarios, investigate cross-module failures, and fix defects found during regression.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A20",
      "activity_name": "Documentation and operational guidance",
      "activity_description": "Document namespace configuration, secure credential prompting, random-port discovery, message-rate configuration, Kafka compatibility notes, deprecated API removals, and the Motion-JPEG spike outcome.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A21",
      "activity_name": "Final review, packaging, and increment handoff",
      "activity_description": "Perform final code review preparation, clean build and packaging, verify change lists and release notes, and prepare the completed increment for handoff.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 656
  }
}

